import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 1000003L

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()

    // Precompute powers of 2 up to 2^(n+2) modulo MOD
    val maxExp = n + 2
    val pow2 = LongArray((maxExp + 1).toInt())
    pow2[0] = 1L
    for (i in 1..maxExp.toInt()) {
        pow2[i] = (pow2[i - 1] * 2L) % MOD
    }

    // Compute S = sum_{k=1}^{n} 2^k * (2^k - 1) mod MOD
    var s = 0L
    for (k in 1..n.toInt()) {
        val pk = pow2[k]
        val term = (pk * ((pk - 1 + MOD) % MOD)) % MOD
        s += term
        if (s >= MOD) s -= MOD
    }

    // total cells = (2n)^2 = 4n^2
    val total = (4L * (n % MOD) % MOD * (n % MOD)) % MOD
    val empty = (total - s + MOD) % MOD

    println(empty)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 1000003L

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()

    // Box side length
    val side = (1L shl n) % MOD
    val totalCells = (side * side) % MOD

    // Number of occupied cells is sum_{k=1..n} 2^{k-1} * (2^k*(2^k+1)/2)
    // Simplifies to (2^{2n+1} - 2)/3
    val pow = modPow(2L, 2L * n + 1L, MOD)
    val occupied = ((pow - 2 + MOD) % MOD) * inv3() % MOD

    val empty = (totalCells - occupied + MOD) % MOD
    println(empty)
}

private fun modPow(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) res = (res * b) % mod
        b = (b * b) % mod
        e = e shr 1
    }
    return res
}

private fun inv3(): Long {
    // Modular inverse of 3 modulo 1_000_003 using Fermat's little theorem
    return modPow(3L, MOD - 2, MOD)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 1000003L

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()

    // For n = 0, box size is 1x1, no cookies fit, so 1 empty cell
    if (n == 0L) {
        println(1)
        return
    }

    // Total cells in 2n x 2n box
    val total = (2L * n) % MOD * ((2L * n) % MOD) % MOD

    // Number of cells covered by cookies:
    // Each cookie of size k covers k*(k+1)/2 cells.
    // The greedy algorithm with infinite cookies of size >=2
    // leads to a fixed pattern; the number of empty cells E(n)
    // satisfies: E(n) = (2n)^2 - 2 * sum_{k=1}^{n} k^2
    // = 4n^2 - 2 * n(n+1)(2n+1)/3
    // We compute this modulo MOD.
    val nn = n % MOD
    val sumSquares = nn * (nn + 1) % MOD * (2 * nn + 1) % MOD * invMod(6L, MOD) % MOD
    val covered = (2L * sumSquares) % MOD

    val empty = (total - covered + MOD) % MOD
    println(empty)
}

// Modular inverse using Fermat's little theorem (MOD is prime)
private fun invMod(a: Long, mod: Long): Long {
    return modPow(a, mod - 2, mod)
}

private fun modPow(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    var e = exp
    var res = 1L
    while (e > 0) {
        if ((e and 1L) != 0L) {
            res = (res * b) % mod
        }
        b = (b * b) % mod
        e = e shr 1
    }
    return res
}

