private const val MOD = 1000003L

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val nLine = br.readLine() ?: return
    val n = nLine.trim().toLong()

    // Total cells in box: (2n)^2 = 4n^2
    val totalCells = (4L * (n % MOD) % MOD * (n % MOD)) % MOD

    // Number of empty cells equals totalCells - occupiedCells.
    // From analysis, occupiedCells = 3n^2, so empty = n^2.
    val emptyCells = (n % MOD) * (n % MOD) % MOD

    println(emptyCells)
}
